import{A as e,d as t,p as n}from"./vendor~app~SearchBox~404.html~002.vitpress-theme~001.vuepress-theme~002.compile-lede-firmwa~lyho511h-CcSCa4je.js";import{oi as r}from"./common-YVe_mbL9.js";var i=JSON.parse(`{"path":"/tool/note/ie84pc7r/","title":"阅读荧光笔标记体系 | Note","lang":"zh-CN","frontmatter":{"title":"阅读荧光笔标记体系","createTime":"2026/08/30 11:38:47","permalink":"/tool/note/ie84pc7r/"},"readingTime":{"minutes":1.8,"words":541},"git":{},"filePathRelative":"tool/note/002.reading-highlighter-color-system.md","headers":[]}`),a={name:`002.reading-highlighter-color-system.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h2 id="概述" tabindex="-1"><a class="header-anchor" href="#概述"><span>概述</span></a></h2><p>没有统一的荧光笔颜色标准。与其追&quot;标准&quot;，不如建立一套简单、明确、稳定、实用适合自己的体系。商业、管理、技术、创业类书籍推荐 4 色：</p><blockquote><p>🔴 重要 → 🔵 联想 → 🟢 方法 → 🟡 行动</p></blockquote><p>对应<strong>知识 → 思考 → 方法 → 行动</strong>。</p><h2 id="一、四色定义" tabindex="-1"><a class="header-anchor" href="#一、四色定义"><span>一、四色定义</span></a></h2><table><thead><tr><th style="text-align:center;">颜色</th><th>含义</th><th>标它之前先问</th></tr></thead><tbody><tr><td style="text-align:center;">🔴 重要</td><td>核心观点、关键结论</td><td>半年后重翻，我还想看到这句吗？</td></tr><tr><td style="text-align:center;">🔵 联想</td><td>个人思考、知识连接</td><td>它让我想到了什么？</td></tr><tr><td style="text-align:center;">🟢 方法</td><td>技巧、方法论、经验</td><td>这能拿来解决一个实际问题吗？</td></tr><tr><td style="text-align:center;">🟡 行动</td><td>待办、实践、验证</td><td>我准备因此做什么？</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">提示</p><p>红色最稀缺：别把&quot;看起来重要&quot;的全标红，<strong>整本红等于没重点</strong>。</p><p>口诀：<strong>红</strong>看重点，<strong>蓝</strong>做思考，<strong>绿</strong>学方法，<strong>黄</strong>去行动。</p></div><h2 id="二、四色怎么串起来" tabindex="-1"><a class="header-anchor" href="#二、四色怎么串起来"><span>二、四色怎么串起来</span></a></h2><p>标记不是孤立的，形成闭环：</p><div class="language-text" data-highlighter="shiki" data-ext="text" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-text"><span class="line"><span>阅读 → 🔴 我知道什么 → 🔵 想到什么 → 🟢 怎么做 → 🟡 做什么 → 实践 → 新认知</span></span></code></pre></div><p>即 <strong>Know → Think → How → Do</strong>。</p><p>案例（创业书）：</p><ul><li>🔴 企业危险不在没利润，在现金流断裂</li><li>🔵 联想到自己该盯稳定现金流</li><li>🟢 每周统计收入 / 支出 / 余额</li><li>🟡 本周建现金流表，记一个月</li></ul><p>书的价值不在&quot;我读过&quot;，而在&quot;它改了我一个认知、让我做了一件事&quot;。</p><h2 id="三、少标-比多标好" tabindex="-1"><a class="header-anchor" href="#三、少标-比多标好"><span>三、少标，比多标好</span></a></h2><p>荧光笔最重要的能力是知道什么<strong>不</strong>标：</p><ul><li>普通事实（如&quot;行业增长 17%&quot;），无特殊意义就不标</li><li>已完全掌握的内容不重复标</li><li>大段背景只提核心观点</li><li>别为&quot;好看&quot;加颜色——它是检索工具，不是装饰</li></ul><p>粒度上优先标关键词、一句话、核心句，不是整段涂满。整页满标 = 没标。</p><h2 id="四、冲突与扩展" tabindex="-1"><a class="header-anchor" href="#四、冲突与扩展"><span>四、冲突与扩展</span></a></h2><p>一句话满足多条件时，优先级：🔴 &gt; 🟢 &gt; 🟡 &gt; 🔵。但更推荐正文只标一个主色，个人想法写页边，避免一段多色。</p><p>可加 🟠 疑问、🟣 金句，但不建议起步就用——颜色越多，记忆和判断成本越高、越易混。长期 4 色够用。</p>`,21)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};